head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.LastJob = "";
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIndex;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gParamObj = new Array(4);
scwin.gISUR_CD;
scwin.gCOM_NM;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode();
        $c.cm.PanelToGroupBox(panel_1);
        // PanelToGroupBox(panel_2);
        // PanelToGroupBox(panel_5);
        // PanelToGroupBox(panel_6);
        // PanelToGroupBox(panel_8);

        MxTab_1.setSelectedTabIndex("1");
        $c.cm.fn_com_isur(txb_tab1_ISUR_CD, txb_tab1_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30603.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    try {
        if (nIndex === '1') {
            scwin.gIndex = nIndex;
            btn_Excel.show("");
            panel_page.show("");
        } else if (nIndex === '2') {
            scwin.gIndex = nIndex;
            btn_Excel.show("");
            panel_page.show("");
        } else if (nIndex === '3') {
            scwin.gIndex = nIndex;
            btn_Excel.show("");
            panel_page.show("");
        } else {
            btn_Excel.hide();
            panel_page.hide();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab1_OnLoadCompleted
 * @description dts_Grid_Tab1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_Tab1_OnLoadCompleted = function(rowcount) {
    try {
        let totalcnt = dts_Grid_Tab1.getCellData(rowcount, "RNUM");
        $c.stf.fillGridHeaderTotalCnt(totalcnt, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.dts_Grid_Tab1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_Tab1_OnLoadError
 * @description dts_Grid_Tab1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_Tab1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid_Tab1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30603.dts_Grid_Tab1_OnLoadError" });
    }
};

