/**
 * @method
 * @name btn_tab1_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_tab1_Search_onclick = async function() {
    try {
        await scwin.tab1Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30603.btn_tab1_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30603.xml", SCREN_PROCS_TP_CD_07, '');
        if (scwin.gIndex === '1') {
            $c.data.downloadGridViewExcel(grd_Grid, {fileName: "기업담당자 목록검색", type: "8"});
        } else if (scwin.gIndex === '2') {
            grd_Grid2.GridToExcel("교육이수현황목록검색", "", "8");
        } else if (scwin.gIndex === '3') {
            grd_Grid3.GridToExcel("교육일정목록검색", "", "8");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        await scwin.readTab1(grd_Grid, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30603.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30603.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        /*
        	cmb_tab4_EDU_KIND_CD.Text="";
        	edt_TAB4_COMPLT_DD.Text="";
        	txb_tab4_DISCLS_EDU_CRS_NM.value="";
        	txb_ATTACH_FILE_NM.value="";
        	dts_FileList.Reset();
         */

        let msg = $c.stf.getMessageParam("MSG-A001", scwin.LastJob);
        await $c.win.alert(msg);
        dts_Tab4_SheEmail.removeAll();
        dts_FileList.removeAll();
        dts_Tab4_SheEmail.insertRow();
        dts_FileList.insertRow();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30603.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        // IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        // tab1 검색버튼
        $c.cm.IsurcdSearch(txb_tab1_ISUR_CD, txb_tab1_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set2(scwin.gISUR_CD, scwin.gCOM_NM);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set2(scwin.gISUR_CD, scwin.gCOM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name cmb_tab1_DEP_CD_onselchange
 * @description cmb_tab1_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_tab1_DEP_CD_onselchange = function() {
    try {
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
        if (cmb_tab1_DEP_CD.getValue() === "") {
            cmb_tab1_EMP_NO.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.cmb_tab1_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        const vVal = cmb_tab1_DEP_CD.getValue();
        if (vVal === "") {
            // 전체일 경우
            return true;
        } else {
            const vVal2 = dts_EMP_NO.getCellData(row, "dep_cd"); // 전체.
            if (vVal2 === "") return true; // 전체.
            return (vVal === vVal2) ? true : false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name txb_tab1_ISUR_CD_onblur
 * @description txb_tab1_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_tab1_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_tab1_ISUR_CD.getValue() === "") {
            txb_tab1_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.txb_tab1_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_tab1_ISUR_CD_onfocus
 * @description txb_tab1_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_tab1_ISUR_CD_onfocus = function() {
    try {
        scwin.gISUR_CD = txb_tab1_ISUR_CD;
        scwin.gCOM_NM = txb_tab1_COM_NM;
        Grd_com_isur.style.top = "65px";
        Grd_com_isur.style.left = "105px";
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.txb_tab1_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_tab1_ISUR_CD_onkeyup
 * @description txb_tab1_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_tab1_ISUR_CD_onkeyup = function() {
    try {
        if (txb_tab1_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.txb_tab1_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30603.MxDataSet_com_isur_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
