/**
 * @method
 * @name tab1Search
 * @description tab1 Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab1Search = async function() {
    const vISUR_CD_tab1 = txb_tab1_ISUR_CD.getValue();
    const vLIST_STAT_CD_tab1 = chb_tab1_LIST_STAT_CD.getValue();
    const vDEP_CD_tab1 = cmb_tab1_DEP_CD.getValue();
    const vEMP_NO_tab1 = cmb_tab1_EMP_NO.getValue();
    const vISTD_INDTP_tab1 = cmb_tab1_STD_INDTP.getValue();
    const vIBAS_YYYY_tab1 = cmb_tab1_BAS_YYYY.getValue();
    url += "&ISUR_CD=" + vISUR_CD_tab1;
    url += "&LIST_STAT_CD=" + vLIST_STAT_CD_tab1;
    url += "&DEP_CD=" + vDEP_CD_tab1;
    url += "&EMP_NO=" + vEMP_NO_tab1;
    url += "&STD_INDTP=" + vISTD_INDTP_tab1;
    url += "&BAS_YYYY=" + vIBAS_YYYY_tab1;
    url += "&MKT_ID=" + js_market;
    url += "&SCREN_ID=" + "ULDSTF30603.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_Grid_Tab1",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid_Tab1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // var vSEARCHTERM = getObjectValue(rdo_SearchTerm);
    let vISUR_CD = txb_isur_cd.getValue();
    const vLIST_STAT_CD = chb_LIST_STAT_CD.getValue();
    const vCOMPLT_YN = cmb_COMPLT_YN.getValue();
    const vCHRG_TP_CD = cmb_CHRG_TP_CD.getValue();
    const vEDU_KIND_CD = cmb_EDU_KIND_CD.getValue();
    const vBAS_YYYY = edt_BAS_YYYY.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    const vISTD_INDTP = cmb_STD_INDTP.getValue();
    const vCORP_CD = cmb_CORP_CD.getValue();
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&LIST_STAT_CD=" + vLIST_STAT_CD;
    url += "&COMPLT_YN=" + vCOMPLT_YN;
    url += "&CHRG_TP_CD=" + vCHRG_TP_CD;
    url += "&EDU_KIND_CD=" + vEDU_KIND_CD;
    url += "&BAS_YYYY=" + vBAS_YYYY;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
