/**
 * @method
 * @name readTab1
 * @description 작업해야함
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readTab1 = async function(GridID, row, colid) {
    // 작업해야함
    let objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    let CMD = "R";
    if (row < 1) return;

    // OPEN
    if (colid === "COM_NM") {
        // 상세화면
        let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        let vCOM_NM = objDataID.getCellData(row, "COM_NM");
        let url = "/issueinfo/ULDSTF30608.gfm?";
        url += "ISUR_CD=" + vISUR_CD;
        url += "&COM_NM=" + vCOM_NM;
        url += "&SCREN_ID=" + "ULDSTF30603.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        if (await scwin.setParam(CMD, vISUR_CD, vCOM_NM)) // formal arguments

        {
            // frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30608.gfm", "공시담당자 이력조회", 200, 10, 810,740, "window");
            $c.frame.path("../../").GWinOpen("ULDSTF30608", url, "공시담당자 이력조회", 10, 20, 810, 740, "");
        }
    }
    if (colid === "CHRG_TP_CDNM") {
        // 공시담당연락처 변경
        let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        let vCOM_NM = objDataID.getCellData(row, "COM_NM");
        if (await scwin.setParam(CMD, vISUR_CD, vCOM_NM)) // formal arguments

        {
            const options = {
                id: "ULDSTF30604",
                title: "공시담당자 연락처변경",
                type: "browserPopup",
                width: "770px",
                height: "400px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/issueinfo/ULDSTF30604.gfm", options);
        }
    }
};

