/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name save
 * @description 관리자 기능
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    const complt_dd = edt_TAB4_COMPLT_DD.getValue();
    const kind_cd = cmb_tab4_EDU_KIND_CD.getValue();
    const edu_nm = txb_tab4_DISCLS_EDU_CRS_NM.getValue();
    const file_nm = txb_ATTACH_FILE_NM.getValue();
    let msg = "";
    if (complt_dd === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "교육일자");
        await $c.win.alert(msg);
        edt_TAB4_COMPLT_DD.focus();
        return;
    }
    if (kind_cd === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "교육구분");
        await $c.win.alert(msg);
        cmb_tab4_EDU_KIND_CD.focus();
        return;
    }
    if (edu_nm === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "교육과정명");
        await $c.win.alert(msg);
        txb_tab4_DISCLS_EDU_CRS_NM.focus();
        return;
    }
    if (file_nm === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "파일");
        await $c.win.alert(msg);
        txb_ATTACH_FILE_NM.focus();
        return;
    }
    let res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        scwin.LastJob = "저장";
        trs_Save.Action = "/ListedCompany.do?method=registerCompanyPersonInChargeAdmFile" + "&SCREN_ID=" + "ULDSTF30603.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Tab4_SheEmail,I:pFile=dts_FileList)";
        trs_Save.post();
    }
};

/**
 * @method
 * @name selectAttach
 * @description 관리자 기능
 * @returns {void}
 * @hidden N
 */
scwin.selectAttach = function() {
    if (file.getValue() === "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};

/**
 * @method
 * @name sendMail
 * @description send Mail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendMail = async function() {
    const email = txb_tab4_EMAIL.getValue();
    const name = txb_tab4_TARGTNAME.getValue();
    const contents = txa_tab4_TARGTCONTENT.getValue();
    let msg = "";
    if (email === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "이메일");
        await $c.win.alert(msg);
        txb_tab4_EMAIL.focus();
        return;
    }
    if ($c.stf.IsValidEmail(email) === false) {
        await $c.win.alert("[이메일] 정확하지 않습니다.");
        txb_tab4_EMAIL.focus();
        return;
    }
    if (name === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "받는이");
        await $c.win.alert(msg);
        txb_tab4_TARGTNAME.focus();
        return;
    }
    if ($c.stf.checkMaxLength(txb_tab4_TARGTNAME, 100, "받는이") === false) {
        return;
    }
    if (contents === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "안내내용");
        await $c.win.alert(msg);
        txa_tab4_TARGTCONTENT.focus();
        return;
    }
    if ($c.stf.checkMaxLength(txa_tab4_TARGTCONTENT, 2000, "안내내용") === false) {
        return;
    }
    let res = window.confirm("[메일]을 전송하시겠습니까?");
    if (res) {
        scwin.LastJob = "메일전송";
        trs_Save.Action = "/ListedCompany.do?method=sendEmail" + "&SCREN_ID=" + "ULDSTF30603.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Tab4_SheEmail)";
        trs_Save.post();
    }
};
